import{_ as a,o as i,c as e,a3 as t}from"./chunks/framework.Ch_0qWu9.js";const d=JSON.parse('{"title":"为 TCSExam 作贡献","description":"","frontmatter":{"sourcePath":".github/CONTRIBUTING.zh-CN.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/aab56977addd5d217972b7f35cf50be4440cb6c7/.github/CONTRIBUTING.zh-CN.md","alternateUrl":"/TCSExam/docs/contributing/","alternateAnchors":{"为-tcsexam-作贡献":"contributing-to-tcsexam","提出新题或更正":"suggest-a-task-or-correction","准备开发工作副本":"set-up-a-development-checkout","检查修改":"check-a-change","编写公开文档":"write-public-documentation","导出源码包":"export-a-source-package","扩展后端或题目资源":"extend-the-backend-or-task-resources","contributing-to-tcsexam":"contributing-to-tcsexam","suggest-a-task-or-correction":"suggest-a-task-or-correction","set-up-a-development-checkout":"set-up-a-development-checkout","check-a-change":"check-a-change","write-public-documentation":"write-public-documentation","export-a-source-package":"export-a-source-package","extend-the-backend-or-task-resources":"extend-the-backend-or-task-resources"}},"headers":[],"relativePath":"zh/contributing/index.md","filePath":"zh/contributing/index.md"}'),n={name:"zh/contributing/index.md"};function h(p,s,c,l,o,r){return i(),e("div",null,[...s[0]||(s[0]=[t(`<p><a id="contributing-to-tcsexam"></a></p><h1 id="为-tcsexam-作贡献" tabindex="-1">为 TCSExam 作贡献 <a class="header-anchor" href="#为-tcsexam-作贡献" aria-label="Permalink to &quot;为 TCSExam 作贡献&quot;">​</a></h1><p>本指南介绍如何贡献研究题目、反馈更正，以及改进代码和文档。 面向希望参与完善 TCSExam 的研究者与开发者。</p><p><a id="suggest-a-task-or-correction"></a></p><h2 id="提出新题或更正" tabindex="-1">提出新题或更正 <a class="header-anchor" href="#提出新题或更正" aria-label="Permalink to &quot;提出新题或更正&quot;">​</a></h2><p>通过 <a href="https://github.com/MoonshotAI/TCSExam/issues" target="_blank" rel="noreferrer">GitHub Issue</a> 提出研究题目或反馈题目问题。请提供题目陈述、来源、所属题型，以及检查提交结果的方法。对于构造题，同时提供参考界及其出处。</p><p>反馈更正时，请注明题目并给出能说明问题的具体例子。已有实现时，可以提交包含题面、验证代码和计分规则的 Pull Request。下方的开发说明列出了需要运行的检查。</p><p><a id="set-up-a-development-checkout"></a></p><h2 id="准备开发工作副本" tabindex="-1">准备开发工作副本 <a class="header-anchor" href="#准备开发工作副本" aria-label="Permalink to &quot;准备开发工作副本&quot;">​</a></h2><p>使用 Python 3.12 或以上版本，安装运行、后端和测试依赖：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv/bin/activate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.[runtime,backend]&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source-inputs</span></span></code></pre></div><p><code>source-inputs</code> 准备 Lean 构建配方和材料测试所用的固定版本源码归档。 上游下载不可用时，使用<a href="/TCSExam/docs/zh/resources/#prepare-fixed-lean-source-archives">经核验的本地导入</a>。</p><p><a id="check-a-change"></a></p><h2 id="检查修改" tabindex="-1">检查修改 <a class="header-anchor" href="#检查修改" aria-label="Permalink to &quot;检查修改&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcsexam.recipes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/tcsexam/backend/tests</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/tcsexam/tests</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-public</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --phase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/source-check.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><p><code>validate</code> 检查题目结构、评测套件成员、脚本执行权限和源码标识。测试套件覆盖 命令配置、数据配方、评分、后端行为和文档链接。<code>check-public --phase source</code> 检查拟分发的源码文件，包括内部引用和分发规则。导出前应解决报告中的错误。</p><p>修改运行逻辑时，还应使用有代表性的输入测试受影响的命令或判分器。执行隔离相关 修改使用<a href="/TCSExam/docs/zh/judge-execution-isolation/">判分镜像预检查</a>；平台适配器使用 <a href="/TCSExam/docs/zh/backend/service/#writing-a-platform-adapter">适配器契约检查</a>。 调整打包方式时，保留题目输入、评分定义和声明的资源预算。</p><p>生成的镜像、下载的数据集和评测输出应放在配置的缓存或输出目录中。 构建配方放在 <code>assets/</code> 下；题目定义放在 <code>tasks/</code> 下，通过 <code>suites/tasks.json</code> 选择。</p><p><a id="write-public-documentation"></a></p><h2 id="编写公开文档" tabindex="-1">编写公开文档 <a class="header-anchor" href="#编写公开文档" aria-label="Permalink to &quot;编写公开文档&quot;">​</a></h2><p>围绕读者的任务组织指南：前置条件、命令、预期输出和故障处理。 每个配置项、输入准备流程和分数只在一份参考文档中定义，其他指南链接到该文档。 中英文指南的命令、默认值和行为说明应保持一致。</p><p><code>docs/</code> 中的 Markdown 是文档内容的源文件，仓库与文档网站共用这些文件。 新增或移动指南时，同时更新<a href="/TCSExam/docs/zh/">文档首页</a>和对应英文页面的导航。 语言切换只链接同一内容的另一语言版本；阅读路径使用独立的内容链接。</p><p>在限制会影响操作的位置说明限制，并写清所需条件和读者应采取的措施。 交付报告、内部评审、开发日记、执行日志和私有基础设施信息应放在源码仓库之外。 保留上游署名、许可文本、来源 URL、固定版本和内容哈希。</p><p>仓库内页面和文件使用相对链接。公开仓库地址维护在 <code>pyproject.toml</code> 的 <code>project.urls.Repository</code> 中。要修改该地址并更新两份入门指南，请运行 <code>python -m tcsexam.project_links --repository-url https://github.com/OWNER/REPOSITORY</code>。 运行 <code>python -m tcsexam.project_links --check</code> 检查一致性。</p><p>默认分支保存评测代码、Markdown 指南和 <code>paper.pdf</code>。 网站源码位于 <a href="https://github.com/MoonshotAI/TCSExam/tree/gh-pages/website" target="_blank" rel="noreferrer"><code>gh-pages</code> 分支的 website 目录</a>。 文档站构建程序读取本分支中的 Markdown 指南。</p><p><a id="export-a-source-package"></a></p><h2 id="导出源码包" tabindex="-1">导出源码包 <a class="header-anchor" href="#导出源码包" aria-label="Permalink to &quot;导出源码包&quot;">​</a></h2><p>使用目标发布提交的干净工作副本，在仓库根目录运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --normalize-modes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/tcsexam-source</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/tcsexam-source</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-public</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/tcsexam-source</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --phase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source</span></span></code></pre></div><p>目标目录必须尚不存在或为空。如果位于工作副本内部，则必须在 <code>build/</code> 下。 导出工具按照分发记录处理文件，排除 Git 元数据、缓存、任务输出、凭据、 参考答案数据和声明为仅供本地使用的输入。导出的目录树包含准备运行环境所需的 配方和获取说明。在导出的工作副本中，进行 Lean 构建或材料测试前，应先运行 <code>tcsexam source-inputs</code>。</p><p>从导出目录创建公开仓库和发布归档。将源码提交、导出清单和检查结果与发布记录 一同保存，以便追溯发布文件的来源。源码工作副本可能包含参考答案和被排除的 输入；发布导出文件时使用全新的 Git 历史。</p><p><code>--normalize-modes</code> 将普通文件权限设为 0644、可执行文件设为 0755、目录设为 0755，同时保留文件内容和可执行状态。不使用该选项时，导出保留源文件权限。</p><p>镜像分发另有<a href="/TCSExam/docs/zh/licenses/distribution/">组件要求</a>。准备包含已发布镜像的 分发产物时，使用 <code>tcsexam check-public --phase release</code>；该检查涵盖镜像地址 和匿名拉取权限。</p><p><a id="extend-the-backend-or-task-resources"></a></p><h2 id="扩展后端或题目资源" tabindex="-1">扩展后端或题目资源 <a class="header-anchor" href="#扩展后端或题目资源" aria-label="Permalink to &quot;扩展后端或题目资源&quot;">​</a></h2><ul><li><a href="/TCSExam/docs/zh/backend/service/#writing-a-platform-adapter">平台适配器契约</a>：worker 创建、 文件传输、执行、资源计量和清理。</li><li><a href="/TCSExam/docs/zh/solver-backend/">后端 HTTP 协议</a>：客户端请求、凭据、会话状态和提交处理。</li><li><a href="/TCSExam/docs/zh/resources/assets/">资源清单</a>：镜像依赖、源码输入和分发记录。</li><li><a href="/TCSExam/docs/zh/backend/public-images/">公开自测镜像</a>：在每个镜像层中将公开数据与隐藏判分 数据分开。</li><li><a href="/TCSExam/docs/zh/oracle-answers/">参考答案归档</a>：将另行提供、供操作者使用的答案打包。</li></ul>`,36)])])}const F=a(n,[["render",h]]);export{d as __pageData,F as default};
